mapper.select:
SELECT COUNT(*) > 0
FROM place_like
WHERE member_id = #{memberId} AND place_id = #{placeId}

mapper.delete:
DELETE
FROM place_like
WHERE member_id = #{memberId} AND place_id = #{placeId}

mapper.select:
SELECT pl.id AS placeLikeId, p.id AS placeId, p.code, p.name, p.address, p.area_code AS areaCode, p.phone, p.url, COALESCE(lc.cnt, 0) AS likeCnt FROM place_like pl JOIN place p ON pl.place_id = p.id LEFT JOIN ( SELECT place_id, COUNT(*) AS cnt FROM place_like GROUP BY place_id ) lc ON lc.place_id = p.id WHERE pl.member_id = #{memberId}
AND pl.id > #{lastId}
ORDER BY pl.id ASC LIMIT #{size}
